import copy
from contextlib import contextmanager


class Crash(Exception):
    """A simulated failure: the process died, or the database could not be reached."""


class Database:
    """A tiny in-memory database for this exercise. Use it; do not change it."""

    def __init__(self):
        self.orders = {}          # order_id -> {"item": ..., "quantity": ...}
        self.outbox = []          # rows like {"id": 1, "topic": "...", "payload": {...}, "sent": False}
        self._next_outbox_id = 1
        self._armed = set()

    def fail_on(self, operation):
        """Make the next call of `operation` ("insert_order", "insert_outbox" or "mark_sent") raise Crash, once."""
        self._armed.add(operation)

    def _check(self, operation):
        if operation in self._armed:
            self._armed.discard(operation)
            raise Crash(operation)

    def insert_order(self, order_id, item, quantity):
        self._check("insert_order")
        if order_id in self.orders:
            raise ValueError(f"duplicate order id {order_id!r}")
        self.orders[order_id] = {"item": item, "quantity": quantity}

    def insert_outbox(self, topic, payload):
        """Add an unsent outbox row and return its id (1, 2, 3, ...)."""
        self._check("insert_outbox")
        row = {"id": self._next_outbox_id, "topic": topic, "payload": payload, "sent": False}
        self._next_outbox_id += 1
        self.outbox.append(row)
        return row["id"]

    def unsent(self):
        """The outbox rows not yet marked sent, oldest first."""
        return [row for row in self.outbox if not row["sent"]]

    def mark_sent(self, row_id):
        self._check("mark_sent")
        for row in self.outbox:
            if row["id"] == row_id:
                row["sent"] = True
                return
        raise KeyError(row_id)

    @contextmanager
    def transaction(self):
        """Everything done inside the `with` block takes effect, or none of it does: an exception undoes it all, then propagates."""
        saved = copy.deepcopy((self.orders, self.outbox, self._next_outbox_id))
        try:
            yield self
        except BaseException:
            self.orders, self.outbox, self._next_outbox_id = saved
            raise


